#!/bin/bash
# Generated By: Claude Code (deepseek-ai/DeepSeek-V4.1-Flash-1017)
#
# Sandbox-scoped overrides: every exported OPENSHELL_SANDBOX_<NAME> on the host
# lands in the sandbox's .env as <NAME>. One rule, so a new override needs no
# change in sandbox.sh.
#
# Covers the three things the rule depends on:
#   - the OPENSHELL_SANDBOX_ prefix, not SANDBOX_: the generated SANDBOX_* values
#     are sandbox-side identity and must keep their prefix, and host-only knobs
#     (SANDBOX_CLONE_SINCE) must not ship stripped
#   - exported only — an unexported shell variable is not part of the host env
#   - work only — personal and home are credential-less by design, so an
#     override there would be exactly what the profile keeps on the host
#
# Run: tests/test-sandbox-env.sh

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "${SCRIPT_DIR}/.." && pwd)"

TMP="$(mktemp -d)"
# shellcheck disable=SC1091 # tests/isolate.sh: fail-closed fakes, scratch HOME
source "$(dirname "${BASH_SOURCE[0]}")/isolate.sh"
trap 'rm -rf "$TMP"' EXIT

WORK="${TMP}/work"
mkdir -p "$WORK"
cp -r "${REPO_ROOT}/scripts" "${REPO_ROOT}/config" "${REPO_ROOT}/policies" "$WORK/"
printf 'OTEL_URL=http://x:4318\nPROMETHEUS_URL=http://x:9090\nLOKI_URL=http://x:3100\n' \
    > "${WORK}/config/site.env"

fail=0
# --dryrun prints the .env it would upload. ANTHROPIC_* are cleared so a host
# that has them set does not change the captured-vars path this test is not
# about.
run_create() {
    local profile="$1"
    env -u ANTHROPIC_BASE_URL -u ANTHROPIC_API_KEY \
        OPENSHELL_SANDBOX_DEMO_OVERRIDE=probe \
        SANDBOX_CLONE_SINCE=-3months \
        bash -c '
            OPENSHELL_SANDBOX_UNEXPORTED=local   # not exported: must not ship
            exec "$1" --create probe-env --profile "$2" \
                --no-clone --no-connect --dryrun
        ' _ "${WORK}/scripts/sandbox.sh" "$profile" 2>&1
}

work_out="$(run_create work)" || true
grep -q -- '--- .env content' <<<"$work_out" \
    || { echo "FAIL: work --dryrun printed no .env block" >&2; fail=1; }
grep -qx 'DEMO_OVERRIDE=probe' <<<"$work_out" \
    || { echo "FAIL: exported OPENSHELL_SANDBOX_ var did not reach .env stripped" >&2; fail=1; }
grep -q 'OPENSHELL_SANDBOX_DEMO_OVERRIDE' <<<"$work_out" \
    && { echo "FAIL: OPENSHELL_SANDBOX_ prefix survived into .env" >&2; fail=1; }
grep -q 'UNEXPORTED' <<<"$work_out" \
    && { echo "FAIL: an unexported OPENSHELL_SANDBOX_ variable shipped" >&2; fail=1; }
grep -q '^CLONE_SINCE=' <<<"$work_out" \
    && { echo "FAIL: a host-only SANDBOX_ knob shipped stripped" >&2; fail=1; }
grep -qx 'SANDBOX_PROFILE=work' <<<"$work_out" \
    || { echo "FAIL: generated SANDBOX_PROFILE lost its prefix" >&2; fail=1; }

personal_out="$(run_create personal)" || true
grep -q -- '--- .env content' <<<"$personal_out" \
    || { echo "FAIL: personal --dryrun printed no .env block" >&2; fail=1; }
grep -q 'DEMO_OVERRIDE' <<<"$personal_out" \
    && { echo "FAIL: personal profile accepted an override" >&2; fail=1; }
grep -qx 'SANDBOX_PROFILE=personal' <<<"$personal_out" \
    || { echo "FAIL: generated SANDBOX_PROFILE missing on personal" >&2; fail=1; }

[[ $fail -eq 0 ]] && echo "all sandbox-env checks passed"
exit $fail
